// Append-only, hash-chained ledger of approvals and the later events that
// affect whether they still hold. Events are never edited; status is derived.
import { createHash, randomUUID } from 'node:crypto';
import { appendFileSync, existsSync, readFileSync } from 'node:fs';

const digest = (s) => createHash('sha256').update(s).digest('hex');

export class ApprovalLedger {
  constructor(path) {
    this.path = path;
  }

  events() {
    if (!existsSync(this.path)) return [];
    return readFileSync(this.path, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
  }

  #append(type, body, at) {
    const prev = this.events().at(-1);
    const event = { id: randomUUID(), type, at: at ?? new Date().toISOString(), ...body, prev: prev?.hash ?? null };
    event.hash = digest(JSON.stringify(event));
    appendFileSync(this.path, JSON.stringify(event) + '\n');
    return event;
  }

  // basis: [{ id, claim, source, config }] — what the approval rested on, as believed at the time.
  approve({ subject, approver, reason, basis }, at) {
    if (!basis?.length) throw new Error('an approval must record at least one basis item');
    if (new Set(basis.map((b) => b.id)).size !== basis.length) throw new Error('basis ids must be unique');
    return this.#append('approval', { subject, approver, reason, basis }, at);
  }

  // The earlier basis item was wrong (e.g. wrong configuration). Arrives any time later.
  correct({ approvalId, basisId, finding, corrected }, at) {
    this.#basisItem(approvalId, basisId);
    return this.#append('correction', { approvalId, basisId, finding, corrected }, at);
  }

  // A trustworthy re-check of the basis item (right config) supports the claim again.
  revalidate({ approvalId, basisId, evidence }, at) {
    this.#basisItem(approvalId, basisId);
    return this.#append('revalidation', { approvalId, basisId, evidence }, at);
  }

  #basisItem(approvalId, basisId) {
    const a = this.events().find((e) => e.type === 'approval' && e.id === approvalId);
    if (!a) throw new Error(`unknown approval ${approvalId}`);
    if (!a.basis.some((b) => b.id === basisId)) throw new Error(`approval has no basis item ${basisId}`);
  }

  verifyChain() {
    let prev = null;
    for (const e of this.events()) {
      const { hash, ...rest } = e;
      if (e.prev !== prev || digest(JSON.stringify(rest)) !== hash) return false;
      prev = hash;
    }
    return true;
  }

  // What the approval rested on, plus whether it still holds, optionally as known at `asOf`.
  report(approvalId, { asOf } = {}) {
    const evs = this.events().filter((e) => !asOf || e.at <= asOf);
    const approval = evs.find((e) => e.type === 'approval' && e.id === approvalId);
    if (!approval) throw new Error(`unknown approval ${approvalId}${asOf ? ` as of ${asOf}` : ''}`);
    const later = evs.filter((e) => e.approvalId === approvalId);
    const basis = approval.basis.map((b) => {
      const hist = later.filter((e) => e.basisId === b.id);
      const last = hist.at(-1);
      const state = !last ? 'intact' : last.type === 'correction' ? 'invalidated' : 'revalidated';
      return { ...b, state, history: hist };
    });
    const broken = basis.filter((b) => b.state === 'invalidated').map((b) => b.id);
    return {
      approvalId,
      subject: approval.subject,
      approver: approval.approver,
      reason: approval.reason,
      approvedAt: approval.at,
      rested_on: basis,
      status: broken.length ? 'no longer holds' : later.length ? 'holds (after review)' : 'holds',
      broken,
      chainIntact: this.verifyChain(),
    };
  }
}

export function format(r) {
  const out = [`${r.subject} — approved by ${r.approver} at ${r.approvedAt}`, `Reason: ${r.reason}`, 'Rested on:'];
  for (const b of r.rested_on) {
    out.push(`  [${b.state}] ${b.id}: ${b.claim} (source: ${b.source}, config: ${JSON.stringify(b.config)})`);
    for (const h of b.history)
      out.push(h.type === 'correction' ? `      ${h.at} corrected: ${h.finding}` : `      ${h.at} revalidated: ${h.evidence}`);
  }
  out.push(`STATUS: ${r.status.toUpperCase()}${r.broken.length ? ` (invalidated: ${r.broken.join(', ')})` : ''}`);
  return out.join('\n');
}
EOF
cat > approval-ledger.test.js <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ApprovalLedger, format } from './approval-ledger.js';

const fresh = () => new ApprovalLedger(join(mkdtempSync(join(tmpdir(), 'led-')), 'l.jsonl'));
const seed = (l) => l.approve({
  subject: 'deploy web@1.4.2', approver: 'agent-7', reason: 'integration suite passed',
  basis: [
    { id: 'tests', claim: 'integration suite: 212/212 pass', source: 'testtool run #88', config: { env: 'staging' } },
    { id: 'scan', claim: 'no critical vulns', source: 'scanner run #12', config: { db: 'current' } },
  ],
}, '2026-10-01T10:00:00Z');

test('holds until a basis item is corrected, original record untouched', () => {
  const l = fresh(); const a = seed(l);
  assert.equal(l.report(a.id).status, 'holds');
  l.correct({ approvalId: a.id, basisId: 'tests', finding: 'run #88 used env=dev, not staging', corrected: { env: 'dev' } }, '2026-10-05T09:00:00Z');
  const r = l.report(a.id);
  assert.equal(r.status, 'no longer holds');
  assert.deepEqual(r.broken, ['tests']);
  assert.equal(r.rested_on[0].config.env, 'staging'); // what it rested on, as recorded
  assert.equal(r.rested_on[1].state, 'intact');
});

test('asOf shows what was known at the time', () => {
  const l = fresh(); const a = seed(l);
  l.correct({ approvalId: a.id, basisId: 'tests', finding: 'wrong config' }, '2026-10-05T09:00:00Z');
  assert.equal(l.report(a.id, { asOf: '2026-10-02T00:00:00Z' }).status, 'holds');
});

test('revalidation restores; later correction wins again', () => {
  const l = fresh(); const a = seed(l);
  l.correct({ approvalId: a.id, basisId: 'tests', finding: 'wrong config' }, '2026-10-05T09:00:00Z');
  l.revalidate({ approvalId: a.id, basisId: 'tests', evidence: 'rerun #91 env=staging: 212/212' }, '2026-10-06T09:00:00Z');
  assert.equal(l.report(a.id).status, 'holds (after review)');
  l.correct({ approvalId: a.id, basisId: 'tests', finding: 'rerun #91 also misconfigured' }, '2026-10-07T09:00:00Z');
  assert.equal(l.report(a.id).status, 'no longer holds');
});

test('tampering is detected; bad references rejected', () => {
  const l = fresh(); const a = seed(l);
  assert.throws(() => l.correct({ approvalId: a.id, basisId: 'nope', finding: 'x' }));
  assert.throws(() => l.approve({ subject: 's', approver: 'a', reason: 'r', basis: [] }));
  writeFileSync(l.path, readFileSync(l.path, 'utf8').replace('integration suite passed', 'edited'));
  assert.equal(l.verifyChain(), false);
});

test('format renders both views', () => {
  const l = fresh(); const a = seed(l);
  l.correct({ approvalId: a.id, basisId: 'tests', finding: 'run #88 used env=dev' }, '2026-10-05T09:00:00Z');
  const s = format(l.report(a.id));
  console.log(s);
  assert.match(s, /STATUS: NO LONGER HOLDS/);
});
EOF
echo '{"type":"module"}' > package.json
node --test 2>&1 | tail -30

